try:
    raise ValueError('x')
except ValueError as e:
    await observe([type(e).__name__,str(e),e.args])

try:
    x=[]
    x.pop()
except IndexError:
    await observe('caught')

try:
    x='a' + 1
except TypeError:
    await observe('type error')

def f(a):
    return a
try:
    f()
except TypeError:
    await observe('missing')

try:
    x=(1).append(2)
except AttributeError:
    await observe('attribute')

def f(flag):
    if flag:
        x=1
    return x
try:
    f(False)
except UnboundLocalError:
    await observe('unbound')

e=ValueError('value')
try:
    raise e from TypeError('cause')
except Exception as err:
    await observe([str(err),str(err.__cause__)])

def f():
    raise
try:
    try:
        raise ValueError('x')
    except ValueError:
        f()
except ValueError as e:
    await observe(str(e))

